(() => {
  'use strict';
  const root = document.getElementById('Studio');
  const routes = { Dashboard:['home','Dashboard'], Focus:['target','Focus Mode'], Apps:['ban','Blocked Apps'], Shield:['shield','Content Shield'], Family:['users','Parental Control'], Activity:['chart','Activity'], DailyLimits:['clock','Daily Limits'], Settings:['settings','Settings'], Profile:['user','Profile'], Setup:['spark','Get started'] };
  const paths = { home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9', target:'M21 12a9 9 0 1 1-9-9m0 4a5 5 0 1 0 5 5m-5 0 8-8m-4 0h4v4', ban:'M5.6 5.6 18.4 18.4', shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Zm-4 9 3 3 5-6', users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M16 3a4 4 0 0 1 0 8', chart:'M4 21V11m5 10V6m5 15V9m5 12V3', clock:'M12 7v5l4 2', settings:'m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3H9Z', user:'M4 21a8 8 0 0 1 16 0', spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z', arrow:'M4 12h16m-6-6 6 6-6 6', chevron:'m9 5 7 7-7 7', search:'m16 16 5 5', bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Zm5 4h4', plus:'M12 5v14M5 12h14', check:'m5 12 4 4L19 6', lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5V10Zm7 5v2', moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z', download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5', heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 9 8 15 7-6 12-11 8-15Z', pause:'M9 5v14M15 5v14', play:'m8 4 12 8-12 8V4Z', reset:'M3 10a9 9 0 1 1 2 9M3 3v7h7', menu:'M4 6h16M4 12h16M4 18h16', close:'m6 6 12 12M6 18 18 6', mail:'M3 5h18v14H3V5Zm0 1 9 7 9-7', calendar:'M4 5h16v16H4V5ZM8 2v6m8-6v6M4 11h16', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z' };
  function icon(key) { const circle = ['ban','clock'].includes(key) ? '<circle cx="12" cy="12" r="9"/>' : key==='search' ? '<circle cx="10" cy="10" r="7"/>' : key==='user'||key==='users' ? '<circle cx="9" cy="7" r="4"/>' : key==='settings'||key==='eye' ? '<circle cx="12" cy="12" r="3"/>' : ''; return `<svg viewBox="0 0 24 24" aria-hidden="true">${circle}<path d="${paths[key]||paths.spark}"/></svg>`; }
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const read = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
  const prefs = read('ControlStudioPreferences.v1',{motion:true,reminders:true,weekly:true,breaks:true,accent:'purple',theme:'Light'});
  let page = 'Dashboard', sample = true, period = 7, selectedApp = null, appCategory = 'All', appQuery = '', usage = null, setupStep = 0;
  let family = read('ControlStudioFamily.v1',[]);
  let focus = read('ControlStudioFocus.v1',{minutes:25,end:0,remaining:0,running:false});
  const appMinutes = {Instagram:54,TikTok:32,YouTube:24,X:18,Snapchat:16,Reddit:0,Threads:0,Facebook:0};
  const colors = {Instagram:'#a087ff',TikTok:'#6260e8',YouTube:'#f7b687',X:'#adb9ed',Snapchat:'#ecd888',Reddit:'#f68c68',Threads:'#b3a6ce',Facebook:'#7baaff'};
  const apps = () => ApplicationDefinitions;
  const duration = minutes => minutes>=60 ? `${Math.floor(minutes/60)}h ${Math.round(minutes%60)}m` : `${Math.round(minutes)}m`;
  const configuredAllowance = () => {
    const total = apps().reduce((sum, app) => sum + (Number(ActiveRules[app.Key].DailyLimitMinutes) || 0), 0);
    return total ? duration(total) : 'Unlimited';
  };
  const name = () => ReadLocalProfile()?.Name || 'to Control';
  const avatar = () => `<span class="CSAvatar">${esc((ReadLocalProfile()?.Name || 'C').slice(0,1))}</span>`;
  const appIcon = key => `<img class="CSAppIcon" src="${(key==='YouTube'?'assets/StudioYouTube.svg':ApplicationIconPaths[key])}" alt=""/>`;
  const currentMinutes = key => sample ? appMinutes[key] || 0 : Math.round((usage?.Days?.[GetLocalDateKey()]?.[key] || 0)/60000);
  const currentTotal = () => apps().reduce((sum,a)=>sum+currentMinutes(a.Key),0);
  const badge = (text,tone='') => `<span class="CSBadge ${tone}">${esc(text)}</span>`;
  const button = (text,action,primary=false,ic='arrow') => `<button type="button" class="CSButton ${primary?'CSPrimary':''}" data-cs-action="${action}">${esc(text)}${ic?icon(ic):''}</button>`;
  const go = (text,route,ic='arrow') => `<button type="button" class="CSButton" data-cs-route="${route}">${esc(text)}${ic?icon(ic):''}</button>`;
  const toggle = (label,checked,attr) => `<button type="button" class="CSSwitch ${checked?'IsOn':''}" role="switch" aria-checked="${Boolean(checked)}" aria-label="${esc(label)}" ${attr}><span></span></button>`;
  const setting = (title,sub,checked,attr,ic='settings') => `<div class="CSSetting">${icon(ic)}<span><strong>${esc(title)}</strong><small>${esc(sub)}</small></span>${toggle(title,checked,attr)}</div>`;
  const cardHead = (title,sub='',ic='spark',extra='') => `<header class="CSCardHeader"><span class="CSIcon">${icon(ic)}</span><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${extra}</header>`;
  function hero(kicker,title,sub,quote='A calmer mind,<br />a brighter you.') { return `<header class="CSHero"><div><p class="CSEyebrow">${kicker}</p><h1 tabindex="-1">${title}</h1><p>${sub}</p></div><aside class="CSQuote"><b>“</b><p>${quote}</p><span>—</span></aside></header>`; }
  function metrics(items) { return `<div class="CSMetrics">${items.map(([label,value,detail,ic],i)=>`<article class="CSMetric ${i%2?'Warm':''}"><span class="CSIcon">${icon(ic)}</span><div><small>${label}</small><strong>${value}</strong><p>${detail}</p></div><span class="CSSpark" aria-hidden="true">${[10,16,13,24,32,39].map(h=>`<i style="height:${h}px"></i>`).join('')}</span></article>`).join('')}</div>`; }
  function dataMode() { return `<div class="CSDataMode"><span class="CSDataDot"></span><span>${sample?'Preview data · example activity':'This device · recorded activity'}</span><button type="button" data-cs-action="sample">${sample?'Use my activity':'Show example'}</button></div>`; }
  function dashboard() { return hero('GOOD TO SEE YOU AGAIN',ReadLocalProfile()?`Welcome back, <em>${esc(name())}.</em>`:'Welcome to <em>Control.</em>','You’re building a calmer, more focused life. Keep going.')+dataMode()+metrics([['Time on social apps',duration(currentTotal()),'Today, across your networks','clock'],['Apps protected',apps().filter(a=>ActiveRules[a.Key].Enabled).length,'Your current preferences','shield'],['Daily boundaries',apps().filter(a=>ActiveRules[a.Key].DailyLimitMinutes>0).length,'Limits set by you','target'],['Focus timer',focus.running?'In progress':'Ready','A little space for what matters','spark']])+`<div class="CSColumns"><article class="CSCard">${cardHead('Your Apps','Control what pulls your attention.','ban',go('Manage apps','Apps','plus'))}<div class="CSMiniTable"><div class="CSTableHead"><span>App</span><span>Protection</span></div>${apps().map(a=>`<div class="CSAppRow">${appIcon(a.Key)}<div><strong>${a.Name}</strong><small>${esc(a.Rules.slice(0,2).map(r=>r[1].replace('Block ','')).join(', '))}</small></div>${toggle(a.Name+' protection',ActiveRules[a.Key].Enabled,`data-cs-rule="${a.Key}.Enabled"`)}<span class="CSStatus">${ActiveRules[a.Key].Enabled?'Protected':'Paused'}</span><button class="CSIconButton" type="button" aria-label="Configure ${a.Name}" data-cs-app="${a.Key}">${icon('chevron')}</button></div>`).join('')}</div></article><div class="CSStack"><article class="CSCard">${cardHead('Content Shield','Choose what you want to keep out.','shield',badge(ActiveRules.SensitiveContentProtection?'Enabled':'Paused','Green'))}${setting('Sensitive content','Filters for supported social pages',ActiveRules.SensitiveContentProtection,'data-cs-rule="SensitiveContentProtection"','shield')}${setting('Strict blocking','Intercept direct links to hidden feeds',ActiveRules.StrictMode,'data-cs-rule="StrictMode"','ban')}${go('Customize protection','Shield')}</article><article class="CSCard">${cardHead('Quick Actions','Take control in one click.','spark')}<div class="CSQuick">${[['Focus','target','Start Focus Mode'],['DailyLimits','clock','Daily Limits'],['Family','users','Your Family'],['Activity','chart','View Activity']].map(([r,i,t])=>`<button type="button" data-cs-route="${r}"><span class="CSIcon">${icon(i)}</span><strong>${t}</strong></button>`).join('')}</div></article></div></div><article class="CSCard CSBottomProfile">${avatar()}<div><strong>${esc(ReadLocalProfile()?.Name||'Your Control space')}</strong><small>${esc(ReadLocalProfile()?.Email||'Your preferences stay on this device')}</small></div><span class="CSBottomDivider"></span><span class="CSIcon">${icon('shield')}</span><div><strong>Private by design</strong><small>No cloud connection required</small></div>${go('Explore your activity','Activity')}</article>`; }
  function shell() {
    root.innerHTML = `<div class="CSLayout"><aside class="CSSidebar"><a class="CSBrand" href="#Home" data-cs-route="Home"><span class="CSLogo"><img src="assets/ControlSelectedBlack.png" alt=""/></span><strong>Control</strong></a><nav aria-label="Control navigation">${Object.entries(routes).filter(([k])=>k!=='Setup').map(([key,[ic,label]])=>`<button type="button" data-cs-route="${key}" class="${['Settings','Profile'].includes(key)?'CSSecondaryNav':''}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="CSSideNote"><span class="CSIcon">${icon('spark')}</span><strong>A little less scrolling.<br />A little more living.</strong><p>Make room for what matters to you.</p>${go('Set up your space','Setup')}</div><a class="CSBackHome" href="#Home" data-cs-route="Home">${icon('arrow')} Back to website</a></aside><div class="CSMain"><header class="CSTopbar"><button type="button" class="CSIconButton CSMenu" data-cs-action="menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button><div class="CSSearch">${icon('search')}<input id="CSSearchInput" type="search" placeholder="Search apps, settings, or help…" aria-label="Search Control" autocomplete="off"/><div id="CSSearchResults" class="CSSearchResults" hidden></div></div><div class="CSTopActions"><button type="button" class="CSIconButton" aria-label="Notifications" data-cs-action="notifications">${icon('bell')}<i></i></button><button type="button" class="CSAccount" data-cs-route="Profile">${avatar()}<span><strong>${esc(ReadLocalProfile()?.Name||'Your profile')}</strong><small>Local workspace</small></span>${icon('chevron')}</button></div></header><main class="CSContent" id="CSContent"></main></div></div><dialog class="CSDialog" id="CSDialog" aria-labelledby="CSDialogTitle"><button type="button" class="CSIconButton CSCloseDialog" aria-label="Close panel" data-cs-action="close-dialog">${icon('close')}</button><div id="CSDialogBody"></div></dialog><div class="CSToast" id="CSToast" role="status" aria-live="polite" hidden></div>`;
    EnsureLogoEyes(root);
    root.querySelector('#CSSearchInput').addEventListener('input', search);
    root.querySelector('#CSSearchInput').addEventListener('keydown',e=> { if(e.key==='Escape') root.querySelector('#CSSearchResults').hidden=true; if(e.key==='Enter') root.querySelector('#CSSearchResults button')?.click(); });
    root.querySelector('#CSDialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});
  }
  function render() {
    const content = root.querySelector('#CSContent');
    if(!content)return;
    const views = {Dashboard:dashboard,Activity:activity,DailyLimits:limits,Apps:blockedApps,Focus:focusPage,Shield:shieldPage,Family:familyPage,Settings:settingsPage,Profile:profilePage,Setup:setupPage};
    content.innerHTML = views[page]();
    EnsureLogoEyes(content);
    root.querySelector('.CSAccount').innerHTML=avatar()+`<span><strong>${esc(ReadLocalProfile()?.Name||'Your profile')}</strong><small>Local workspace</small></span>${icon('chevron')}`;
    root.querySelector('.CSAccount').setAttribute('aria-label','Open your profile');
    content.classList.remove('CSEntering'); void content.offsetWidth; content.classList.add('CSEntering');
    root.dataset.reduceMotion=String(!prefs.motion);
    root.dataset.accent=prefs.accent;
    root.dataset.studioTheme=prefs.theme;
    root.querySelectorAll('.CSSidebar [data-cs-route]').forEach(b=>{b.classList.toggle('Active',b.dataset.csRoute===page);if(b.dataset.csRoute===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
    tick();
  }
  function open(route) {
    if(!routes[route]) { ShowSection(route); return; }
    page=route; selectedApp=null;
    document.querySelectorAll('.PageSection').forEach(el=>el.classList.toggle('IsVisible',el===root));
    document.documentElement.dataset.currentSection='Studio';
    document.getElementById('Onboarding').hidden=true;
    document.body.classList.remove('OnboardingActive');
    root.classList.remove('CSNavOpen');
    root.querySelector('.CSMenu')?.setAttribute('aria-expanded','false');
    history.replaceState(null,'',`#${route}`);
    render(); window.scrollTo({top:0,behavior:'instant'});
    document.title=`${routes[route][1]} · Control`;
    if(!usage) void ReadUsageStats().then(v=>{usage=v;if(v?.Days&&Object.values(v.Days).some(d=>Object.values(d).some(n=>n>0))){sample=false;render();}}).catch(()=>{});
  }
  function toast(message) {const el=root.querySelector('#CSToast');el.innerHTML=icon('check')+`<span>${esc(message)}</span>`;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,2600);}
  function modal(title,body) {root.querySelector('#CSDialogBody').innerHTML=`<h2 id="CSDialogTitle">${esc(title)}</h2>${body}`;root.querySelector('#CSDialog').showModal();}
  function search() {const q=root.querySelector('#CSSearchInput').value.trim().toLowerCase();const list=root.querySelector('#CSSearchResults');list.hidden=!q;if(!q)return;const matches=Object.entries(routes).filter(([,v])=>v[1].toLowerCase().includes(q));list.innerHTML=matches.map(([r,[i,l]])=>`<button type="button" data-cs-route="${r}">${icon(i)}${l}</button>`).join('')+apps().filter(a=>a.Name.toLowerCase().includes(q)).map(a=>`<button type="button" data-cs-app="${a.Key}">${appIcon(a.Key)}${a.Name}</button>`).join('');if(!list.innerHTML)list.innerHTML='<p>No results. Try “Activity” or an app name.</p>';}
  function activity() { return hero('YOUR TIME, CLEARLY','Activity','Understand your habits. Make more room for what matters.','Small changes.<br />More time for you.')+dataMode()+metrics([['Time today',duration(currentTotal()),'Across your social apps','clock'],['Daily average',sample?'2h 19m':duration(GetRecentDays(7).reduce((s,d)=>s+apps().reduce((n,a)=>n+(usage?.Days?.[GetLocalDateKey(d)]?.[a.Key]||0)/60000,0),0)/7),sample?'Example, last seven days':'Last seven days · this device','chart'],['Most used app',sample?'Instagram':mostUsed(),sample?'54 minutes today':'Based on recorded activity','target'],['Apps with activity',apps().filter(a=>currentMinutes(a.Key)>0).length,'Networks used today','spark']])+`<div class="CSActivityColumns"><article class="CSCard CSChartCard">${cardHead('Time on your networks','Select a day to see the breakdown.','chart',`<div class="CSSegmented">${[1,7,30].map(n=>`<button type="button" data-cs-period="${n}" class="${period===n?'Active':''}">${n===1?'Today':n+' days'}</button>`).join('')}</div>`)}${chart()}<div class="CSChartLegend">${apps().map(a=>`<span><i style="background:${colors[a.Key]}"></i>${a.Name}</span>`).join('')}</div><p id="CSChartSelection" class="CSChartSelection">${sample?'Example activity, not your measured screen time.':'Only recorded foreground time is counted.'}</p></article><article class="CSCard">${cardHead('Today’s balance','Time by application','clock')}<div class="CSDonut" style="--segments:${donut()}"><div><strong>${duration(currentTotal())}</strong><small>social time</small></div></div>${apps().map(a=>`<div class="CSLegendRow"><i style="background:${colors[a.Key]}"></i><span>${a.Name}</span><strong>${duration(currentMinutes(a.Key))}</strong></div>`).join('')}</article></div><article class="CSCard">${cardHead('Your daily breakdown','See how your time compares with your boundaries.','chart',go('Edit limits','DailyLimits'))}<div class="CSUsageTable">${apps().map(a=>{const used=currentMinutes(a.Key),limit=ActiveRules[a.Key].DailyLimitMinutes;return `<div class="CSUsageRow">${appIcon(a.Key)}<strong>${a.Name}</strong><div class="CSProgress" aria-label="${a.Name}: ${used} minutes"><i style="width:${Math.min(100,limit?used/limit*100:0)}%;background:${colors[a.Key]}"></i></div><span>${duration(used)} <small>/ ${limit?duration(limit):'no limit'}</small></span>${badge(limit&&used>=limit?'Limit reached':'Within limit',limit&&used>=limit?'Orange':'Green')}</div>`;}).join('')}</div></article>`; }
  function mostUsed(){return apps().slice().sort((a,b)=>currentMinutes(b.Key)-currentMinutes(a.Key))[0]&&currentTotal()?apps().slice().sort((a,b)=>currentMinutes(b.Key)-currentMinutes(a.Key))[0].Name:'No activity';}
  function donut(){let offset=0,total=currentTotal();if(!total)return '#eeebf8 0% 100%';return apps().map(a=>{let start=offset;offset+=currentMinutes(a.Key)/total*100;return `${colors[a.Key]} ${start}% ${offset}%`;}).join(',');}
  function chart() {
    const count=period===1?(sample?8:1):period;const dates=GetRecentDays(count);const totals=Array.from({length:count},(_,i)=>sample?(period===1?[5,14,7,32,21,38,18,9][i]:[168,126,102,154,117,164,144][i%7]):apps().reduce((s,a)=>s+(usage?.Days?.[GetLocalDateKey(dates[i])]?.[a.Key]||0)/60000,0));
    const max=Math.max(...totals,60);
    return `<div class="CSChart" style="--columns:${count}"><div class="CSChartGrid"><span>${duration(max)}</span><span>${duration(max/2)}</span><span>0m</span></div><div class="CSChartBars">${totals.map((total,i)=>`<button type="button" class="CSChartBar" data-cs-day="${i}" data-total="${total}" aria-label="${period===1?(sample?(i*3)+':00':'Today'):dates[i].toLocaleDateString('en-US',{month:'short',day:'numeric'})}: ${duration(total)}"><span class="CSBarTotal">${duration(total)}</span><span class="CSBarTrack"><span class="CSBarStack" style="height:${Math.max(1,total/max*100)}%">${apps().map(a=>`<i style="flex:${sample?appMinutes[a.Key]:Math.max(0,usage?.Days?.[GetLocalDateKey(dates[i])]?.[a.Key]||0)};background:${colors[a.Key]}"></i>`).join('')}</span></span><small>${period===1?(sample?(i*3)+'h':'Today'):count>7?(i%5===0?dates[i].getDate():''):dates[i].toLocaleDateString('en-US',{weekday:'short'})}</small></button>`).join('')}</div></div>`;
  }
  function limitClock(key,n) {
    const maximum=Math.max(180,n), fraction=n/maximum;
    const ticks=Array.from({length:60},(_,i)=>`<line x1="100" y1="${i%5?18:13}" x2="100" y2="22" transform="rotate(${i*6} 100 100)" class="${i%5?'':'Major'}"/>`).join('');
    return `<div class="CSLimitClock ${n?'':'Unlimited'}" data-clock="${key}" data-maximum="${maximum}" data-draft="${n}" role="slider" tabindex="${n?0:-1}" aria-disabled="${!n}" aria-label="${key} daily allowance" aria-valuemin="0" aria-valuemax="${maximum}" aria-valuenow="${n}" aria-valuetext="${n?duration(n):'Unlimited'}">
      <svg viewBox="0 0 200 200" aria-hidden="true"><circle class="CSClockTrack" cx="100" cy="100" r="92"/><circle class="CSClockArc" cx="100" cy="100" r="92" pathLength="100" stroke-dasharray="${fraction*100} 100" transform="rotate(-90 100 100)"/><g class="CSClockTicks">${ticks}</g><g class="CSClockHand" transform="rotate(${fraction*360} 100 100)"><line x1="100" y1="38" x2="100" y2="27"/><circle cx="100" cy="8" r="5"/></g></svg>
      <span class="CSClockValue"><small>DAILY ALLOWANCE</small><strong data-limit-value="${key}">${n?duration(n):'∞'}</strong><span>${n?'per day':'Unlimited'}</span></span>
    </div>`;
  }
  function limits(){
    return hero('A HEALTHIER RHYTHM','Daily Limits','Choose your time. Keep the rest of your day open.','Your time.<br />Your boundaries.')+dataMode()+`<div class="CSLimitSummary"><span class="CSIcon">${icon('clock')}</span><div><strong>${apps().filter(a=>ActiveRules[a.Key].DailyLimitMinutes>0).length} active limits</strong><span>Unlimited unless you choose a limit</span></div><p>Resets at midnight.<br />Removing a limit keeps your activity history.</p></div><div class="CSLimitGrid">${apps().map(a=>{
      const n=Number(ActiveRules[a.Key].DailyLimitMinutes)||0,used=currentMinutes(a.Key);
      return `<article class="CSCard CSLimitCard" data-limit-card="${a.Key}"><header>${appIcon(a.Key)}<div><h2>${a.Name}</h2><small>${n?'Your daily rhythm':'No daily restriction'}</small></div>${badge(n?'Limited':'Unlimited')}</header>
      ${limitClock(a.Key,n)}
      <p class="CSClockHint">${n?'Drag the hand · use arrow keys for 5 minutes':'Time is unlimited. Add a boundary when you want.'}</p>
      ${n?`<div class="CSClockAdjust"><button type="button" aria-label="Decrease ${a.Name} limit by 5 minutes" data-cs-adjust="-5" data-app="${a.Key}">−</button><span>5 minutes</span><button type="button" aria-label="Increase ${a.Name} limit by 5 minutes" data-cs-adjust="5" data-app="${a.Key}">+</button></div><div class="CSPresets">${[15,30,45,60].map(m=>`<button type="button" class="${n===m?'Active':''}" data-cs-preset="${m}" data-app="${a.Key}">${m} min</button>`).join('')}</div><button type="button" class="CSButton CSRemoveLimit" data-cs-remove-limit="${a.Key}" aria-label="Remove ${a.Name} daily limit">${icon('reset')} Remove daily limit</button>`:`<button type="button" class="CSButton CSPrimary CSAddLimit" data-cs-preset="30" data-app="${a.Key}" aria-label="Set ${a.Name} daily limit">${icon('plus')} Set a daily limit</button>`}
      <footer><span>${duration(used)} used today</span><strong>${n?duration(Math.max(0,n-used))+' left':'No limit'}</strong></footer></article>`;
    }).join('')}</div>`;
  }
  function blockedApps(){return hero('DISTRACTION CONTROLS','Blocked Apps','Choose which apps and content to block, limit, or customize.','Fewer distractions.<br />A more intentional you.')+`<div class="CSColumns"><article class="CSCard">${cardHead('Apps & Feeds','Control the apps and content that pull you in.','ban')}<div class="CSAppFilters"><div class="CSSegmented">${['All','Social Media','Video'].map(c=>`<button type="button" data-cs-category="${c}" class="${c===appCategory?'Active':''}">${c}</button>`).join('')}</div><label class="CSInlineSearch">${icon('search')}<input type="search" id="CSAppSearch" placeholder="Search apps…" value="${esc(appQuery)}" aria-label="Search apps"/></label></div><div id="CSAppRows">${appRows()}</div></article><div class="CSStack"><article class="CSCard">${cardHead('Your Protection','Your saved preferences','shield')}${[['ban',apps().filter(a=>ActiveRules[a.Key].Enabled).length+' apps protected','Choose protection per network'],['clock',apps().filter(a=>ActiveRules[a.Key].DailyLimitMinutes).length+' time limits','Daily limits set'],['settings','Custom filters','Keep the parts you need']].map(([i,t,s])=>`<div class="CSInfoRow"><span class="CSIcon">${icon(i)}</span><div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}${go('Manage daily limits','DailyLimits')}</article><article class="CSCard">${cardHead('Make it your own','Every application has its own controls.','spark')}<p>Open an app to choose what stays. Keep messages, remove distracting feeds, and set a daily boundary.</p><span class="CSLocalNote">${icon('lock')} Saved on this device</span></article></div></div>`;}
  function appRows(){const filtered=apps().filter(a=>a.Name.toLowerCase().includes(appQuery.toLowerCase())&&(appCategory==='All'||(appCategory==='Video'?['YouTube','TikTok'].includes(a.Key):!['YouTube'].includes(a.Key))));return filtered.length?`<div class="CSAppTableHead"><span>App / Feed</span><span>Status</span><span>Daily limit</span></div>${filtered.map(a=>`<div class="CSAppListRow">${appIcon(a.Key)}<div><strong>${a.Name}</strong><small>${esc(a.Rules.slice(0,2).map(r=>r[1]).join(', '))}</small></div>${toggle(a.Name+' protection',ActiveRules[a.Key].Enabled,`data-cs-rule="${a.Key}.Enabled"`)}<span class="CSAppAllowance">${ActiveRules[a.Key].DailyLimitMinutes?duration(ActiveRules[a.Key].DailyLimitMinutes)+'/day':'No limit'}</span><button type="button" class="CSIconButton" data-cs-app="${a.Key}" aria-label="Configure ${a.Name}">${icon('chevron')}</button></div>`).join('')}`:'<div class="CSEmpty">No apps match your search.</div>';}
  function appPanel(key){const a=apps().find(x=>x.Key===key);if(!a)return;selectedApp=key;modal(a.Name,`<p>Choose exactly what stays available.</p><div class="CSDialogApp">${appIcon(key)}<strong>${a.Name}</strong>${badge('Local preferences')}</div>${setting('Protect this app','Apply your chosen filters',ActiveRules[key].Enabled,`data-cs-rule="${key}.Enabled"`,'shield')}<div class="CSRuleList">${a.Rules.map(([r,l,d])=>setting(l,d,ActiveRules[key][r],`data-cs-rule="${key}.${r}"`,'ban')).join('')}</div><div class="CSDialogFooter">${go('Adjust daily limit','DailyLimits','clock')}${button('Done','close-dialog',true,'check')}</div>`);}
  function focusPage(){return hero('PROTECT YOUR ATTENTION','Focus Mode','One thing at a time. Give it your full attention.','Less noise.<br />More headspace.')+`<div class="CSFocusGrid"><article class="CSCard CSFocusCard"><span class="CSBadge">Local focus timer</span><div class="CSFocusRing"><svg viewBox="0 0 240 240" aria-hidden="true"><circle cx="120" cy="120" r="108"/><circle id="CSFocusProgress" cx="120" cy="120" r="108"/></svg><div><span id="CSFocusState">Ready to focus</span><strong id="CSFocusTime">25:00</strong><small>Make space for what matters</small></div></div><div class="CSPresets">${[15,25,45,60].map(m=>`<button type="button" data-cs-focus-minutes="${m}" class="${focus.minutes===m?'Active':''}" ${focus.running?'disabled':''}>${m} min</button>`).join('')}</div><div class="CSFocusActions">${button(focus.running?'Pause session':focus.remaining?'Resume session':'Start focus','focus-toggle',true,focus.running?'pause':'play')}${button('Reset','focus-reset',false,'reset')}</div><p>This timer runs here. Your application filters remain independently configurable.</p></article><div class="CSStack"><article class="CSCard">${cardHead('Your focus preferences','A quieter space for your next session.','target')}${setting('Focus reminders','Gentle prompts in this workspace',prefs.reminders,'data-cs-pref="reminders"','bell')}${setting('Grayscale browsing','Reduce visual stimulation in supported apps',ActiveRules.GrayscaleMode,'data-cs-rule="GrayscaleMode"','eye')}${setting('In-app usage timer','See your time on supported social pages',ActiveRules.ShowUsageTimer,'data-cs-rule="ShowUsageTimer"','clock')}</article><article class="CSCard">${cardHead('Protect your session','Keep useful connections. Remove the feeds.','shield')}${apps().map(a=>`<div class="CSFocusApp">${appIcon(a.Key)}<strong>${a.Name}</strong>${toggle(a.Name+' protection',ActiveRules[a.Key].Enabled,`data-cs-rule="${a.Key}.Enabled"`)}</div>`).join('')}</article></div></div>`;}
  function shieldPage(){return hero('YOUR PEACE OF MIND','Content Shield','Choose the boundaries that make your online space feel better.','Keep the good.<br />Filter the rest.')+`<div class="CSColumns"><article class="CSCard">${cardHead('Privacy & Content','Preferences for the current extension.','shield')}${setting('Sensitive content protection','Use the extension’s existing local content filters',ActiveRules.SensitiveContentProtection,'data-cs-rule="SensitiveContentProtection"','shield')}${setting('Strict blocking','Intercept direct links to blocked feeds',ActiveRules.StrictMode,'data-cs-rule="StrictMode"','ban')}${setting('Shield every social app','Pause access to all configured networks',ActiveRules.ShieldAll,'data-cs-rule="ShieldAll"','lock')}<div class="CSCallout">${icon('shield')}<p>These controls use your current extension settings. No browsing history is sent to a database.</p></div></article><article class="CSCard">${cardHead('Your custom list','Add domains to your local preferences.','plus')}<form id="CSDomainForm" class="CSInlineForm"><input name="domain" placeholder="example.com" aria-label="Domain to filter" required/><button type="submit" class="CSButton CSPrimary">Add ${icon('plus')}</button></form><div class="CSChips">${(read('ControlStudioDomains.v1',[])).map(d=>`<span>${esc(d)}<button type="button" aria-label="Remove ${esc(d)}" data-cs-remove-domain="${esc(d)}">${icon('close')}</button></span>`).join('')||'<p class="CSEmpty">Your list is empty. Add a domain to preview your custom rules.</p>'}</div><p class="CSFine">Custom lists on this screen are a local design preview; enforcement will be connected later.</p></article></div>`;}
  function familyPage(){return hero('SAFER KIDS. BRIGHTER TOMORROWS.','Parental Control','Create a calmer digital routine for your family.','Better habits.<br />Together.')+`<div class="CSCallout">${icon('users')}<p>Family workspace preview. Profiles stay on this device; remote monitoring and device restrictions are not connected.</p></div><div class="CSColumns"><article class="CSCard">${cardHead('Your Family','A personal space for each child.','users',button('Add child','add-child',false,'plus'))}<div class="CSFamilyGrid">${family.length?family.map((child,i)=>`<article class="CSChild"><span class="CSChildAvatar">${esc(child.name.slice(0,1))}</span><h3>${esc(child.name)}</h3><p>Age ${child.age}</p>${badge('Not connected')}<div class="CSChildMetric">${icon('clock')}<span>${child.limit} min daily allowance</span></div><div>${button('Manage',`child-${i}`,false,'settings')}${button(child.locked?'Unlock preview':'Quick lock',`lock-child-${i}`,true,'lock')}</div></article>`).join(''):`<div class="CSEmpty CSFamilyEmpty"><span class="CSIcon">${icon('users')}</span><h3>Your family, in one place.</h3><p>Add a local profile to explore limits and schedules.</p>${button('Add a child profile','add-child',true,'plus')}</div>`}</div></article><div class="CSStack"><article class="CSCard">${cardHead('Family Controls','Preview your family preferences.','users')}${setting('Parental approvals','Preference only · device connection required',prefs.approvals||false,'data-cs-pref="approvals"','lock')}${setting('Bedtime reminders','Build a quieter evening routine',prefs.bedtime||false,'data-cs-pref="bedtime"','moon')}</article><article class="CSCard">${cardHead('Screen Time & Schedules','Build habits at your own pace.','clock')}<div class="CSInfoRow">${icon('calendar')}<div><strong>Daily screen time</strong><small>Set individually in each child’s profile</small></div></div><div class="CSInfoRow">${icon('moon')}<div><strong>Bedtime routine</strong><small>Choose a local schedule for each profile</small></div></div></article></div></div>`;}
  function settingsPage(){return hero('SETTINGS','Profile & Settings','Manage your preferences and privacy. You’re in control.','Better habits.<br />A brighter you.')+`<article class="CSCard CSBottomProfile">${avatar()}<div><h2>${esc(ReadLocalProfile()?.Name||'Your Control profile')}</h2><small>${esc(ReadLocalProfile()?.Email||'Personalize your local workspace')}</small></div>${badge('Local profile')}${go(ReadLocalProfile()?'View profile':'Sign in',ReadLocalProfile()?'Profile':'Login')}</article><div class="CSSettingsGrid"><article class="CSCard">${cardHead('General','Make Control feel at home.','settings')}${setting('Show usage timer','A timer inside supported social pages',ActiveRules.ShowUsageTimer,'data-cs-rule="ShowUsageTimer"','clock')}${setting('Grayscale browsing','A quieter visual experience',ActiveRules.GrayscaleMode,'data-cs-rule="GrayscaleMode"','eye')}<div class="CSSetting"><span><strong>Preferred workspace</strong><small>Choose your default overview</small></span><select aria-label="Start page" data-cs-select-pref="startPage">${['Dashboard','Activity','Focus'].map(v=>`<option ${prefs.startPage===v?'selected':''}>${v}</option>`).join('')}</select></div></article><article class="CSCard">${cardHead('Notifications','Your preferences, ready for connection.','bell')}${setting('Weekly progress report','Local preference · email not connected',prefs.weekly,'data-cs-pref="weekly"','mail')}${setting('Focus reminders','Notifications inside this workspace',prefs.reminders,'data-cs-pref="reminders"','target')}${setting('Break suggestions','Local preference for future reminders',prefs.breaks,'data-cs-pref="breaks"','clock')}</article><article class="CSCard">${cardHead('Appearance','A space that feels like yours.','spark')}<div class="CSSetting"><span><strong>Theme</strong><small>Your workspace appearance</small></span><select aria-label="Theme" data-cs-select-pref="theme"><option ${prefs.theme==='Light'?'selected':''}>Light</option><option ${prefs.theme==='Dark'?'selected':''}>Dark</option></select></div><div class="CSSetting"><span><strong>Accent color</strong><small>Pick your favorite shade</small></span><div class="CSSwatches">${['purple','blue','pink','orange'].map(c=>`<button type="button" data-cs-accent="${c}" class="${prefs.accent===c?'Active':''}" aria-label="${c} accent" aria-pressed="${prefs.accent===c}"></button>`).join('')}</div></div>${setting('Reduce motion','Use minimal interface animation',!prefs.motion,'data-cs-pref="reduce-motion"','eye')}</article><article class="CSCard">${cardHead('Privacy & Content','Keep your experience intentional.','shield')}${setting('Strict blocking','Protect your chosen boundaries',ActiveRules.StrictMode,'data-cs-rule="StrictMode"','shield')}${setting('Sensitive content shield','Use your existing extension filters',ActiveRules.SensitiveContentProtection,'data-cs-rule="SensitiveContentProtection"','ban')}${go('Customize content filters','Shield')}</article><article class="CSCard">${cardHead('Your account','Your identity and local preferences.','user')}${go(ReadLocalProfile()?'Manage profile':'Sign in or create an account',ReadLocalProfile()?'Profile':'Login','user')}${button('Download my preferences','export',false,'download')}<p class="CSFine">Account synchronization will be connected later.</p></article><article class="CSCard">${cardHead('Need help?','We’re here for you.','heart')}${button('Open support desk','support',false,'mail')}${go('Set up Control','Setup','spark')}${go('Back to website','Home')}</article></div>`;}
  function profilePage(){return hero('YOUR SPACE','Your Profile','A little more you. A little less distraction.')+`<div class="CSColumns"><article class="CSCard CSProfileCard">${avatar()}<h2>${esc(ReadLocalProfile()?.Name||'Your profile')}</h2><p>${esc(ReadLocalProfile()?.Email||'Sign in to add your identity.')}</p>${badge('On this device')}<div class="CSProfileStats"><div><strong>${apps().filter(a=>ActiveRules[a.Key].Enabled).length}</strong><small>apps protected</small></div><div><strong>${family.length}</strong><small>family profiles</small></div></div>${ReadLocalProfile()?button('Sign out','signout',false,'arrow'):go('Sign in','Login')}${button('Download preferences','export',false,'download')}</article><div class="CSStack"><article class="CSCard">${cardHead('Your preferences','Keep shaping your own space.','settings')}${go('Appearance & settings','Settings')}${go('Daily time limits','DailyLimits','clock')}${go('Family workspace','Family','users')}</article><article class="CSCard">${cardHead('Private by design','Your settings stay close.','lock')}<p>Your profile and preferences are stored locally. Cloud synchronization and connected devices will be available after the account services are connected.</p></article></div></div>`;}
  function setupPage(){const titles=['Welcome to a calmer day.','Choose your applications.','Set a healthy boundary.','Your space is ready.'];return `<section class="CSSetup"><div class="CSSetupProgress">${titles.map((_,i)=>`<span class="${i<=setupStep?'Active':''}">${i<setupStep?icon('check'):i+1}</span>`).join('')}</div><p class="CSEyebrow">YOUR CONTROL SETUP · ${setupStep+1} / 4</p><h1>${titles[setupStep]}</h1><p>${['A few simple choices. Everything can be changed later.','Keep the connections you need. Filter the rest.','Choose a starting daily allowance for your apps.','Your local preferences are saved. Make yourself at home.'][setupStep]}</p><article class="CSCard">${setupStep===0?`<span class="CSSetupLogo"><img src="assets/ControlSelectedBlack.png" alt="Control"/></span><h2>Less scrolling. More living.</h2><p>Control brings your applications, focus sessions and daily limits together in one calm space.</p>`:setupStep===1?apps().map(a=>`<div class="CSFocusApp">${appIcon(a.Key)}<strong>${a.Name}</strong>${toggle(a.Name+' protection',ActiveRules[a.Key].Enabled,`data-cs-rule="${a.Key}.Enabled"`)}</div>`).join(''):setupStep===2?`<span class="CSIcon">${icon('clock')}</span><h2>Start with 30 minutes.</h2><p>A gentle daily boundary for every social app. Adjust each one in Daily Limits whenever you want.</p>${button('Apply 30 min to every app','limits-all',true,'check')}`:`<span class="CSSetupDone">${icon('check')}</span><h2>You’re in control.</h2><p>${apps().filter(a=>ActiveRules[a.Key].Enabled).length} apps protected · Your choices stay editable.</p>${go('Review daily limits','DailyLimits','clock')}`}</article><div class="CSSetupActions">${setupStep?button('Back','setup-back',false,''):go('Back to dashboard','Dashboard','')}${button(setupStep===3?'Open dashboard':'Continue','setup-next',true)}</div></section>`;}
  async function saveRule(path,value){
    const pieces=path.split('.');
    if(pieces.length===2)ActiveRules[pieces[0]][pieces[1]]=value;else ActiveRules[path]=value;
    try {
      const result=await WriteStoredRules(ActiveRules);
      SynchronizeDuplicateSwitches(path,value);
      toast(result.connected?'Applied to your extension':'Saved locally · extension not connected');
      return true;
    } catch { toast('Not applied. Check the extension connection and try again.');return false; }
  }
  function refreshRulesUI(){
    if(root.querySelector('#CSContent'))render();
    root.querySelectorAll('[data-cs-rule]').forEach(el=>{
      const keys=el.dataset.csRule.split('.');
      const value=keys.length===2?ActiveRules[keys[0]][keys[1]]:ActiveRules[keys[0]];
      el.classList.toggle('IsOn',!!value);el.setAttribute('aria-checked',String(!!value));
    });
  }
  window.addEventListener('control:rules-ready',refreshRulesUI);
  window.addEventListener('control:rules-updated',refreshRulesUI);
  window.addEventListener('control:sync-state',()=>{
    const status=root.querySelector('.CSSyncStatus');
    if(status){status.dataset.state=ControlSyncState.state;status.querySelector('p').textContent=ControlSyncState.message;}
  });
  let draggingClock=null;
  function drawClock(el,n) {
    const fraction=n/Number(el.dataset.maximum);
    el.dataset.draft=n;el.setAttribute('aria-valuenow',n);el.setAttribute('aria-valuetext',duration(n));
    el.querySelector('[data-limit-value]').textContent=duration(n);
    el.querySelector('.CSClockArc').setAttribute('stroke-dasharray',fraction*100+' 100');
    el.querySelector('.CSClockHand').setAttribute('transform','rotate('+fraction*360+' 100 100)');
  }
  function pointClock(el,e) {
    const rect=el.getBoundingClientRect();
    const angle=(Math.atan2(e.clientX-rect.left-rect.width/2,-(e.clientY-rect.top-rect.height/2))+Math.PI*2)%(Math.PI*2);
    const n=Math.max(5,Math.round(angle/(Math.PI*2)*Number(el.dataset.maximum)/5)*5);
    drawClock(el,n);
  }
  root.addEventListener('pointerdown',e=>{
    const el=e.target.closest('[data-clock]');
    if(!el||el.getAttribute('aria-disabled')==='true'||e.button!==0)return;
    draggingClock=el;el.setPointerCapture(e.pointerId);el.focus();pointClock(el,e);e.preventDefault();
  });
  root.addEventListener('pointermove',e=>{if(draggingClock)pointClock(draggingClock,e);});
  root.addEventListener('pointerup',async()=>{
    if(!draggingClock)return;
    const el=draggingClock,key=el.dataset.clock;draggingClock=null;
    await saveRule(key+'.DailyLimitMinutes',Number(el.dataset.draft));render();
    root.querySelector('[data-clock="'+key+'"]')?.focus();
  });
  root.addEventListener('pointercancel',()=>{draggingClock=null;render();});
  root.addEventListener('keydown',async e=>{
    const el=e.target.closest('[data-clock]');
    if(!el||el.getAttribute('aria-disabled')==='true'||!['ArrowUp','ArrowRight','ArrowDown','ArrowLeft','Home','End'].includes(e.key))return;
    e.preventDefault();
    const max=Number(el.dataset.maximum),current=Number(el.dataset.draft);
    const n=e.key==='Home'?5:e.key==='End'?max:Math.max(5,Math.min(max,current+(['ArrowUp','ArrowRight'].includes(e.key)?5:-5)));
    drawClock(el,n);const key=el.dataset.clock;
    await saveRule(key+'.DailyLimitMinutes',n);render();root.querySelector('[data-clock="'+key+'"]')?.focus();
  });
  function persistPrefs(){localStorage.setItem('ControlStudioPreferences.v1',JSON.stringify(prefs));}
  function persistFocus(){localStorage.setItem('ControlStudioFocus.v1',JSON.stringify(focus));}
  function tick(){const left=focus.running?Math.max(0,Math.ceil((focus.end-Date.now())/1000)):focus.remaining||focus.minutes*60;if(focus.running&&left===0){focus.running=false;focus.remaining=0;persistFocus();if(prefs.reminders)toast('Session complete. Take a little break.');if(page==='Focus')render();}const time=root.querySelector('#CSFocusTime');if(time){time.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;root.querySelector('#CSFocusState').textContent=focus.running?'You’re making space':focus.remaining?'Take your time':'Ready to focus';root.querySelector('#CSFocusProgress').style.strokeDashoffset=679*(1-left/(focus.minutes*60));}}
  root.addEventListener('input',e=>{if(e.target.id==='CSAppSearch'){appQuery=e.target.value;root.querySelector('#CSAppRows').innerHTML=appRows();}if(e.target.dataset.csRange){const key=e.target.dataset.csRange;root.querySelector(`[data-limit-value="${key}"]`).textContent=duration(+e.target.value);}});
  root.addEventListener('change',async e=>{if(e.target.dataset.csRange){await saveRule(e.target.dataset.csRange+'.DailyLimitMinutes',+e.target.value);render();}if(e.target.dataset.csSelectPref){prefs[e.target.dataset.csSelectPref]=e.target.value;persistPrefs();render();toast('Preference saved');}});
  root.addEventListener('click',async e=>{
    if(root.classList.contains('CSNavOpen') && e.target.closest('.CSMain')) {root.classList.remove('CSNavOpen');root.querySelector('.CSMenu').setAttribute('aria-expanded','false');return;}
    const b=e.target.closest('button,a');if(!b)return;
    if(b.dataset.csRoute){e.preventDefault();root.querySelector('#CSDialog').close();root.querySelector('#CSSearchResults').hidden=true;open(b.dataset.csRoute);return;}
    if(b.dataset.csApp){appPanel(b.dataset.csApp);return;}
    if(b.dataset.csRule){const value=b.getAttribute('aria-checked')!=='true';b.disabled=true;await saveRule(b.dataset.csRule,value);b.disabled=false;return;}
    if(b.dataset.csPref){const k=b.dataset.csPref;if(k==='reduce-motion')prefs.motion=!prefs.motion;else prefs[k]=!prefs[k];persistPrefs();render();toast('Preference saved');return;}
    if(b.dataset.csAccent){prefs.accent=b.dataset.csAccent;persistPrefs();render();return;}
    if(b.dataset.csRemoveLimit){await saveRule(b.dataset.csRemoveLimit+'.DailyLimitMinutes',0);render();return;}
    if(b.dataset.csAdjust){const k=b.dataset.app;await saveRule(k+'.DailyLimitMinutes',Math.max(5,Math.min(1440,ActiveRules[k].DailyLimitMinutes+Number(b.dataset.csAdjust))));render();return;}
    if(b.dataset.csLimitEnabled){const k=b.dataset.csLimitEnabled;await saveRule(k+'.DailyLimitMinutes',ActiveRules[k].DailyLimitMinutes?0:30);render();return;}
    if(b.dataset.csPreset){await saveRule(b.dataset.app+'.DailyLimitMinutes',+b.dataset.csPreset);render();return;}
    if(b.dataset.csPeriod){period=+b.dataset.csPeriod;render();return;}
    if(b.dataset.csDay){root.querySelectorAll('.CSChartBar').forEach(el=>el.classList.toggle('Selected',el===b));root.querySelector('#CSChartSelection').textContent=b.getAttribute('aria-label')+(sample?' · Example data':' · Recorded time');return;}
    if(b.dataset.csCategory){appCategory=b.dataset.csCategory;render();return;}
    if(b.dataset.csFocusMinutes){focus={minutes:+b.dataset.csFocusMinutes,end:0,remaining:0,running:false};persistFocus();render();return;}
    if(b.dataset.csRemoveDomain){const domains=read('ControlStudioDomains.v1',[]).filter(d=>d!==b.dataset.csRemoveDomain);localStorage.setItem('ControlStudioDomains.v1',JSON.stringify(domains));render();return;}
    const action=b.dataset.csAction;if(!action)return;
    if(action==='close-dialog')root.querySelector('#CSDialog').close();
    else if(action==='menu'){const on=root.classList.toggle('CSNavOpen');b.setAttribute('aria-expanded',String(on));}
    else if(action==='sample'){sample=!sample;render();}
    else if(action==='notifications')modal('Your notifications','<div class="CSNotification"><span class="CSIcon">'+icon('heart')+'</span><div><h3>A little progress, every day.</h3><p>Your workspace is ready. Start a focus session or explore your activity.</p></div></div><p class="CSFine">Account and email notifications are not connected yet.</p>');
    else if(action==='limits-all'){apps().forEach(a=>ActiveRules[a.Key].DailyLimitMinutes=30);await WriteStoredRules(ActiveRules);render();toast('Daily allowances set to 30 minutes');}
    else if(action==='focus-toggle'){if(focus.running){focus.remaining=Math.max(1,Math.ceil((focus.end-Date.now())/1000));focus.running=false;}else{focus.end=Date.now()+(focus.remaining||focus.minutes*60)*1000;focus.running=true;}persistFocus();render();}
    else if(action==='focus-reset'){focus.running=false;focus.remaining=0;focus.end=0;persistFocus();render();toast('Focus timer reset');}
    else if(action==='setup-next'){if(setupStep===3){prefs.setupDone=true;persistPrefs();open('Dashboard');}else{setupStep++;render();}}
    else if(action==='setup-back'){setupStep=Math.max(0,setupStep-1);render();}
    else if(action==='add-child')childDialog();
    else if(action.startsWith('child-'))childDialog(+action.slice(6));
    else if(action.startsWith('lock-child-')){const child=family[+action.slice(11)];child.locked=!child.locked;localStorage.setItem('ControlStudioFamily.v1',JSON.stringify(family));render();toast(child.locked?'Lock preview enabled · no device is connected':'Lock preview disabled');}
    else if(action==='support'){document.getElementById('ZipSupportDesk').hidden=false;document.body.classList.add('ModalIsOpen');}
    else if(action==='signout'){SignOutAccount();RenderLocalProfile();window.ControlAuth?.setMode('signin');ShowSection('Login');}
    else if(action==='export'){const blob=new Blob([JSON.stringify({preferences:prefs,rules:ActiveRules},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='control-preferences.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Preferences downloaded');}
  });
  function childDialog(index){const child=family[index]||{name:'',age:10,limit:60,bedtime:'21:00'};modal(index===undefined?'Add a child profile':'Manage '+child.name,`<p>A local preview profile. No device will be connected.</p><form id="CSChildForm" data-index="${index??''}" class="CSForm"><label>Name<input name="name" value="${esc(child.name)}" maxlength="40" required/></label><div class="CSFormPair"><label>Age<input name="age" type="number" min="1" max="17" value="${child.age}" required/></label><label>Daily limit (minutes)<input name="limit" type="number" min="5" max="480" step="5" value="${child.limit}" required/></label></div><label>Bedtime<input type="time" name="bedtime" value="${esc(child.bedtime)}" required/></label><button type="submit" class="CSButton CSPrimary">Save profile ${icon('check')}</button></form>`);}
  root.addEventListener('submit',e=>{if(e.target.id==='CSDomainForm'){e.preventDefault();const input=e.target.elements.domain;const domain=input.value.trim().toLowerCase().replace(/^https?:\/\//,'').replace(/\/.*$/,'');if(!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(domain)){input.setCustomValidity('Enter a domain such as example.com');input.reportValidity();input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});return;}const domains=read('ControlStudioDomains.v1',[]);if(!domains.includes(domain))domains.push(domain);localStorage.setItem('ControlStudioDomains.v1',JSON.stringify(domains));render();toast('Domain saved in local preview');}if(e.target.id==='CSChildForm'){e.preventDefault();const f=new FormData(e.target);const child={name:f.get('name').trim(),age:+f.get('age'),limit:+f.get('limit'),bedtime:f.get('bedtime'),locked:false};if(!child.name)return;const i=e.target.dataset.index;if(i==='')family.push(child);else family[+i]={...family[+i],...child};localStorage.setItem('ControlStudioFamily.v1',JSON.stringify(family));root.querySelector('#CSDialog').close();render();toast('Local family profile saved');}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){root.classList.remove('CSNavOpen');root.querySelector('.CSMenu')?.setAttribute('aria-expanded','false');root.querySelector('#CSSearchResults').hidden=true;}});
  window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(routes[r])ShowSection(r);});
  window.ControlStudio={open,supports:r=>Boolean(routes[r]),enter:()=>open(prefs.startPage||'Dashboard')};
  shell();
  if(routes[document.documentElement.dataset.currentSection]) open(document.documentElement.dataset.currentSection);

  setInterval(tick,1000);
})();
